style.css:
/* Styling for the body element */
body {
  background-color: lightblue; /* Sets the background color of the entire page */
}

/* Styling for h1 (heading 1) elements */
h1 {
  color: white; /* Sets the text color to white */
  text-align: center; /* Centers the text horizontally */
}

/* Styling for p (paragraph) elements */
p {
  font-family: verdana; /* Sets the font family to Verdana */
  font-size: 20px; /* Sets the font size to 20 pixels */
}
